   "content": "import \"./globals.css\";\n\nexport const metadata = { title: \"__TITLE__\", description: \"__DESCRIPTION__\" };\n\nexport default function RootLayout({ children }) {\n  return (\n    <html lang=\"en\">\n      <body>{children}</body>\n    </html>\n  );\n}\n"
