   "path": "package.json",
   "content": "{\n  \"name\": \"devstack-template-app\",\n  \"version\": \"0.1.0\",\n  \"private\": true,\n  \"scripts\": {\n    \"dev\": \"next dev\",\n    \"build\": \"next build\",\n    \"start\": \"npx serve@14.2.5 out\"\n  },\n  \"dependencies\": {\n    \"next\": \"16.4.2\",\n    \"react\": \"19.3.1\",\n    \"react-dom\": \"19.3.1\"\n  },\n  \"engines\": { \"node\": \">=20\" }\n}\n"
